CustomField.formula:
IF(
/*If Account is Country Parent, stores Industry Override value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Industry_Override__c,
IF(
/*If Account is Sales site, stores Country Parent Account's Industry Override by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Industry_Override__c,
IF(
/*If Account is Parent HQ, stores Country Parent Account's Industry Override by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Parent HQ'), Parent.Industry_Override__c,Industry_Override__c)))
